# Study notes for the second wave of the library: lay life, in full.
# Each entry: title, known, setting, brief, teaching (list), living (optional), topics, related.
def S(title, known, setting, brief, teaching, topics, related=(), living=''):
    d = {'title': title, 'known': known, 'setting': setting, 'brief': brief, 'teaching': list(teaching), 'topics': list(topics), 'related': list(related)}
    if living: d['living'] = living
    return d

LAY2 = {
# ---------------- household ----------------
'an3.31': S('Living with Brahmā', 'Sabrahmaka Sutta', 'Sāvatthī. A short teaching to the mendicants on the household.',
  'Families where the parents are honoured are said to live **with Brahmā**, with **the first teachers** and with **those worthy of offerings**. These are all names for mother and father, because parents do so much for their children: they raise them, nourish them and show them the world.',
  ['Parents are called **Brahmā**, **first teachers** (*pubbācariya*) and **worthy of offerings** (*āhuneyya*).',
   'The reason is gratitude: they bring us up, feed us and introduce us to the world.',
   'The verses: honour them with food and drink, clothes and bedding, bathing and anointing, washing their feet. Do this and you are praised here and rejoice in heaven.'],
  ['parents', 'gratitude', 'family'], ['an2.33', 'iti106', 'an4.63'],
  'The divine is not placed somewhere far away. It is placed at your own dinner table. The verses are concrete: food, clothing, a bed, a bath, washing the feet of the old. Caring for ageing parents is presented as worship.'),
'iti106': S('Mother and Father as Brahmā', 'Sabrahmaka Sutta (Itivuttaka)', 'Itivuttaka, the Book of Fours: sayings recorded by the laywoman Khujjuttarā.',
  'The same teaching as AN 3.31, preserved in a second collection. Where children honour their parents, that family lives with Brahmā, with the first teachers, and with the gods of old.',
  ['Parents as **Brahmā**, as **the first gods** (*pubbadeva*), as **the first teachers**, as **worthy of offerings**.',
   'Each title rests on what parents have done: raising, nourishing, showing the world.',
   'The closing verses ask the wise to honour them in deed and in service.'],
  ['parents', 'gratitude'], ['an3.31', 'an2.33']),
'an4.197': S('Queen Mallikā\'s Question', 'Mallikā Sutta', 'Sāvatthī. Queen Mallikā, wife of King Pasenadi, comes to the Buddha with a frank question.',
  'Why are some women plain, poor and without influence, others beautiful, rich and powerful? The Buddha links each to a habit of heart: **anger** to appearance, **not giving** to poverty, **jealousy** to lack of influence. Mallikā resolves on the spot to give up anger, to give, and to rejoice in others\' success.',
  ['**Anger and irritability** bear fruit as an unattractive appearance.',
   '**Not giving** food, drink, clothing, lodging and light to renunciants bears fruit as poverty.',
   '**Jealousy** of others\' gains and honours bears fruit as lack of influence.',
   'Mallikā: from today I will not be angry, I will give, and I will not envy.'],
  ['karma', 'anger', 'generosity', 'jealousy'], ['mn135', 'an5.31']),
'an5.33': S('Advice to Uggaha\'s Daughters', 'Uggaha Sutta', 'Bhaddiya, Jātiyā Wood. The householder Uggaha asks the Buddha to advise his daughters, who are about to marry.',
  'A father\'s request and a teacher\'s answer: five qualities for a young wife joining her husband\'s family, which lead to rebirth among the "Agreeable" gods. The household roles are of their time; the qualities beneath them (diligence, courtesy, care for the people in the home, stewardship of income, and a life of faith and virtue) are not.',
  ['Rise before your husband, retire after him, be willing in service, pleasant in conduct and kind in speech.',
   'Honour those he respects: his parents and the renunciants, with a seat and water when they come.',
   'Be skilled and tireless in the work of the house.',
   'Know the work and the health of everyone in the household, and give each their fair share of food.',
   'Guard the household\'s income and do not waste it. Be a lay follower of faith and virtue.'],
  ['marriage', 'household', 'family'], ['an4.53', 'an7.63', 'an8.49']),
'an8.46': S('The Agreeable Gods', 'Anuruddha Sutta', 'Jetavana. Gods of the "Agreeable" realm (manāpakāyika) dance for Venerable Anuruddha, who asks the Buddha how a woman is reborn among them.',
  'Eight qualities lead a woman to the Agreeable gods: the five of AN 5.33 for household life, plus going for refuge, keeping the precepts, and delighting in giving.',
  ['Courtesy, kind speech and willing service at home.',
   'Respect for parents and renunciants.',
   'Skill in household work and fair care for the household staff.',
   'Protection of the family\'s earnings.',
   'Refuge, the five precepts, and a generous heart free of stinginess.'],
  ['household', 'family', 'virtue'], ['an5.33', 'an8.49']),
'an8.49': S('Success in This Life and the Next', 'Idhalokika Sutta · Lokavijaya Sutta', 'Sāvatthī, the Eastern Monastery built by the laywoman Visākhā.',
  'Four qualities bring success in this world: being **capable at work**, **managing the household well**, **behaving agreeably to one\'s partner**, and **protecting what has been earned**. Four more bring success in the next: **faith, virtue, generosity and wisdom**.',
  ['**This life:** organised and tireless at work; caring for the people of the household; faithful in the marriage; guarding the income from loss, theft and waste.',
   '**The next:** faith in the Buddha\'s awakening; the five precepts; a heart free of stinginess, open-handed and fond of sharing; insight into rise and fall.',
   'BJT names it the "conquest of the world" (*lokavijaya*).'],
  ['household', 'success', 'wealth', 'faith'], ['an8.54', 'an5.33']),
# ---------------- wealth ----------------
'an10.91': S('Ten Kinds of People Who Enjoy Wealth', 'Kāmabhogī Sutta', 'Sāvatthī. The Buddha teaches Anāthapiṇḍika, his greatest lay supporter.',
  'The most complete ethical map of wealth in the canon. People who live the household life are sorted on four questions: **How was the money made? Do they enjoy it themselves? Do they share it and make merit? And how do they hold it: with greed, or seeing its danger and knowing the way out?**',
  ['**Seeking:** unrighteously and by violence; partly righteously; or righteously, without violence.',
   '**Using:** not enjoying it, enjoying it, and sharing it and doing good with it.',
   '**Holding:** tied, infatuated and blind to the danger; or free, seeing the danger and knowing the escape.',
   'The best of all seeks righteously, enjoys it, shares it, does good with it, and uses it without being bound by it.',
   'The same teaching is given to the headman Rāsiya in SN 42.12.'],
  ['earning', 'spending', 'ethics', 'wealth'], ['an8.54', 'an4.61', 'sn42.12'],
  'Run your own finances through the four questions once a year. Most people stop at the first two. The Buddha\'s finest wealthy person is also generous and also free: he owns his wealth and it does not own him.'),
'an5.47': S('Noble Wealth', 'Dhana Sutta', 'Sāvatthī. A short teaching on the treasures no one can take.',
  'Five kinds of wealth that cannot be lost to kings, thieves, fire, flood or heirs: **faith, virtue, learning, generosity and wisdom**. A person who has them is not poor, and their life is not lived in vain. AN 7.6 gives the fuller list of seven.',
  ['**Faith** in the Buddha\'s awakening.', '**Virtue**: the five precepts.', '**Learning**: having heard and remembered much.',
   '**Generosity**: living at home with a heart free of stinginess.', '**Wisdom**: insight into rise and fall that leads to the end of suffering.'],
  ['wealth', 'faith', 'virtue'], ['an7.6', 'an8.54']),
'snp1.4': S('The Farmer Bhāradvāja', 'Kasibhāradvāja Sutta', 'Ekanāḷā, Magadha, at sowing time. The brahmin farmer Kasibhāradvāja is handing out food to his workers when the Buddha arrives for alms.',
  'The farmer challenges the Buddha: "I plough and sow, then eat. You should do the same." The Buddha says he too ploughs and sows, and describes a spiritual farm, in a famous set of verses. The farmer is moved and offers milk-rice; the Buddha declines food given for reciting verses. The farmer later goes forth and becomes an arahant.',
  ['**Faith is the seed**, austerity the rain, wisdom the yoke and plough.',
   '**Conscience is the pole**, mind the strap, mindfulness the ploughshare and goad.',
   'Guarded in body and speech, moderate in food; **truth is the weeding**.',
   'Energy is the ox that carries one to the place where there is no sorrow: this ploughing yields the deathless.'],
  ['work', 'livelihood', 'faith'], ['an4.62', 'snp2.14']),
# ---------------- giving ----------------
'an4.57': S('Suppavāsā\'s Gift', 'Suppavāsā Sutta', 'Sajjanela, among the Koliyans. The laywoman Suppavāsā serves the Buddha a meal with her own hands.',
  'A woman who gives food gives four things: **long life, beauty, happiness and strength**. Giving them, she shares in them, whether among humans or gods.',
  ['The four gifts of a meal: life (*āyu*), beauty (*vaṇṇa*), happiness (*sukha*), strength (*bala*).',
   'The giver receives what she gives.',
   'Verses: food well prepared, given in season to the upright, is praised by the wise.'],
  ['giving', 'food', 'merit'], ['an5.37', 'an5.36']),
'an5.31': S('Princess Sumanā', 'Sumanā Sutta', 'Sāvatthī. Princess Sumanā arrives with five hundred chariots and five hundred maidens.',
  'Two disciples are equal in faith, virtue and wisdom; one gives, one does not. Is there a difference? The Buddha says yes, in five ways (life, beauty, happiness, honour and authority), as gods, as humans, and even as monastics, where the generous one is the one people ask to accept their gifts. Only at full awakening is there no difference.',
  ['Generosity makes a measurable difference even between equally virtuous people.',
   'The five excellences: lifespan, beauty, happiness, glory, sovereignty.',
   'At arahantship, "there is no difference between one freedom and another."'],
  ['giving', 'karma'], ['an5.34', 'an4.197']),
'an5.34': S('General Sīha', 'Sīhasenāpati Sutta', 'Vesālī. Sīha, a general and a former follower of the Jains, asks whether giving bears fruit you can see for yourself.',
  'Four fruits of giving are visible in this life, and the fifth comes after death. Sīha says he knows the first four from his own experience and takes the fifth on trust.',
  ['The giver is **dear to many people**.', '**Good people** keep company with them.', 'A **good reputation** spreads.',
   'They enter any assembly with **confidence**.', 'After death they are reborn in a **good place**.'],
  ['giving', 'reputation', 'leadership'], ['an5.35', 'an7.62']),
'an5.36': S('Timely Gifts', 'Kāladāna Sutta', 'Sāvatthī.',
  'Five gifts given at the right moment: **to a newcomer**, **to one setting out on a journey**, **to the sick**, **in a time of famine**, and **the first fruits of field and orchard** to the virtuous. The verses (*kāle dadanti sappaññā*) are among the best known in Sri Lanka.',
  ['Give to someone newly arrived, and to someone about to leave.', 'Give to the sick.', 'Give when food is scarce.',
   'Offer the first of the harvest to the virtuous.',
   'Verses: those who rejoice in a gift, or serve, share in the merit too; the gift is not diminished.'],
  ['giving', 'timing', 'merit'], ['an5.37', 'an5.148']),
'an5.37': S('A Meal', 'Bhojana Sutta', 'Sāvatthī.',
  'The giver of a meal gives five things to the recipient: **life, beauty, happiness, strength and eloquence**. And by giving them, the giver comes to share in them. The verses begin *āyudo balado dhīro*, and are chanted as a blessing after alms.',
  ['Five gifts in one meal: life, beauty, happiness, strength, quickness of mind (*paṭibhāna*).',
   'What is given returns as long life and glory wherever one is reborn.'],
  ['giving', 'food', 'blessing'], ['an4.57', 'an5.36']),
'an6.37': S('A Gift with Six Factors', 'Chaḷaṅgadāna Sutta', 'Sāvatthī. The laywoman Veḷukaṇṭakī Nandamātā is offering a meal to the Saṅgha led by Sāriputta and Moggallāna.',
  'A gift is complete in six factors, three on the giver\'s side and three on the receivers\'. The merit of such a gift cannot be measured, any more than the water in the ocean can be counted in buckets.',
  ['**Giver:** glad before giving; inspired while giving; satisfied after giving.',
   '**Receivers:** free of greed, hatred and delusion, or practising to remove them.',
   'Merit beyond measure: "this much merit" cannot be said, as the ocean\'s water cannot be counted.'],
  ['giving', 'intention', 'merit'], ['an7.52', 'mn142']),
'an3.57': S('Vacchagotta and the Ethics of Giving', 'Vacchagotta Sutta', 'Sāvatthī. Vacchagotta has heard a rumour that the Buddha tells people to give only to him and his disciples.',
  'The Buddha rejects the rumour. Whoever discourages another\'s gift obstructs three people. He says even tipping dishwater into a pool to feed the small creatures there makes merit. Then he adds the distinction that runs through all the giving suttas: gifts to the virtuous bear greater fruit.',
  ['Obstructing a gift harms three: the giver\'s merit, the recipient\'s gain, and oneself.',
   'Even rinse water given to creatures makes merit.',
   'Gifts to those free of the five hindrances and endowed with virtue, concentration, wisdom, freedom and knowledge are of great fruit.'],
  ['giving', 'tolerance', 'merit'], ['sn3.24', 'mn142']),
'an8.33': S('Eight Reasons for Giving', 'Dānavatthu Sutta', 'Sāvatthī.',
  'People give for eight reasons: **favouritism**, **anger**, **confusion**, **fear**, because "my family always gave", for **heaven**, because **it brightens the mind**, and because **it adorns and equips the mind**. The last is the finest.',
  ['Giving out of desire, hate, delusion or fear.', 'Giving from custom: "it was done by my ancestors."', 'Giving for a heavenly rebirth.',
   'Giving because it gladdens the mind.', 'Giving "as an ornament and requisite of the mind" (*cittālaṅkāra cittaparikkhāra*).'],
  ['giving', 'intention'], ['an8.35', 'an6.37']),
'an8.35': S('Rebirth by Giving', 'Dānūpapatti Sutta', 'Sāvatthī.',
  'Someone gives and sets their heart on a particular rebirth: a wealthy human family, or one of the heavens up to the Brahmā world. If they are virtuous, the aspiration can be fulfilled, "because the heart\'s wish of a virtuous person succeeds through purity." For the Brahmā world, one must also be free of sensual desire.',
  ['Eight rebirths a giver may aspire to, from prosperous humans to the Brahmā realm.',
   'The aspiration is fulfilled for the **virtuous**, not for the unvirtuous.',
   'The Brahmā realm requires freedom from sensual desire.'],
  ['giving', 'rebirth', 'aspiration'], ['an8.36', 'mn142']),
'an8.36': S('Grounds for Making Merit', 'Puññakiriyavatthu Sutta', 'Sāvatthī.',
  'Three grounds for making merit: **giving, virtue and meditation**. Practised to a small, moderate or great extent, they lead to rebirth from the less fortunate among humans up through the heavens. This sutta lies behind the Sri Lankan triad *dāna, sīla, bhāvanā*.',
  ['**Dāna** (giving), **sīla** (virtue), **bhāvanā** (meditation).',
   'The degree of practice shapes the rebirth.',
   'The commentaries expand the three into ten grounds of merit, adding respect, service, sharing merit, rejoicing in merit, teaching, listening and straightening one\'s views.'],
  ['merit', 'giving', 'virtue', 'meditation'], ['an8.39', 'iti22']),
'an8.39': S('Streams of Merit', 'Abhisanda Sutta', 'Sāvatthī.',
  'Eight streams of merit flow into happiness. Three are the refuges. The other five are called **great gifts**: the five precepts. Someone who keeps them gives fearlessness, safety and goodwill to countless beings, and has a share in that same freedom from fear.',
  ['Going for refuge to the Buddha, the Dhamma and the Saṅgha.',
   'The five precepts as **five great gifts** (*mahādāna*): primordial, traditional, uncorrupted, not rejected by the wise.',
   'Abstaining from killing gives fearlessness to countless beings.'],
  ['precepts', 'merit', 'refuge'], ['an5.179', 'sn55.7']),
'an7.62': S('Don\'t Fear Merit', 'Mā Puññabhāyī Sutta · Metta Sutta', 'Sāvatthī.',
  '"Don\'t be afraid of merit," the Buddha says: it is another word for happiness. He recalls a past life in which he developed loving-kindness for seven years. For seven aeons he did not return to this world. He was Brahmā, Sakka thirty-six times, and a righteous wheel-turning king many hundreds of times.',
  ['Merit (*puñña*) is a name for happiness: desirable, lovely, pleasing.',
   'Seven years of mettā bore fruit for aeons.',
   'The verses urge training in giving, calm conduct and a heart of love.'],
  ['merit', 'mettā', 'happiness'], ['iti22', 'an11.15']),
'iti22': S('Do Not Fear Merit', 'Mā Puññabhāyī Sutta', 'Itivuttaka, the Book of Ones.',
  'A shorter telling of AN 7.62: merit means happiness, and the Buddha recalls the long fruit of seven years of loving-kindness.',
  ['"Do not be afraid of merit."', 'Train in good deeds that bring long happiness: giving, peaceful living, a heart of love.'],
  ['merit', 'mettā'], ['an7.62', 'iti27']),
'kp7': S('Outside the Walls', 'Tirokuṭṭa Sutta', 'The Khuddakapāṭha. The commentary sets it in Rājagaha, when King Bimbisāra\'s departed relatives appeared to him after he had made an offering without sharing its merit.',
  'The departed stand outside walls and at crossroads, hoping for a share. Where there is no farming or trade in their world, they live on what is given here. Weeping and grieving do not help them. A gift given to the Saṅgha in their name helps them for a long time. This is the canonical root of the Sri Lankan practice of offering alms and sharing merit for the dead (*mataka dāna*).',
  ['"May this be for our relatives; may our relatives be happy" (*idaṃ vo ñātīnaṃ hotu*).',
   'There is no trade or herding there; the departed live on what is given here.',
   'Tears and lamentation do not help them; an offering well placed in the Saṅgha does.',
   'Such a gift honours the dead, strengthens the monks, and makes great merit.'],
  ['grief', 'merit', 'death', 'family'], ['kp8', 'sn3.22']),
'kp8': S('The Treasure Store', 'Nidhikaṇḍa Sutta', 'The Khuddakapāṭha.',
  'A man buries treasure against a day of need, but it may be lost: forgotten, taken by spirits, stolen, or spent by an heir. The treasure that cannot be lost is the one laid up by **giving, virtue, restraint and self-control**. It follows you, and it brings every good thing, up to nibbāna.',
  ['Buried treasure is never secure.',
   'Treasure placed in a shrine, the Saṅgha, a person, a guest, mother, father or elder brother is "well buried".',
   'It cannot be stolen; it follows the giver; every human and divine success is won by it.'],
  ['merit', 'wealth', 'investment'], ['an5.227', 'an4.61']),
# ---------------- conduct ----------------
'an8.41': S('The Uposatha in Brief', 'Saṅkhitta Uposatha Sutta', 'Sāvatthī.',
  'The uposatha with eight factors. Each precept is taken with the same reflection: "For life, the arahants keep this. Today, for this day and night, I will keep it too." Observed like this, it is of great fruit.',
  ['Refraining from killing, stealing and all sexual activity.',
   'Refraining from lying and from alcohol.',
   'Refraining from eating after noon, from entertainment and adornment, and from high and luxurious beds.',
   '"I will imitate the arahants for one day and night."'],
  ['uposatha', 'precepts'], ['an8.42', 'an3.70', 'an9.18']),
'an8.42': S('The Uposatha in Detail', 'Vitthata Uposatha Sutta', 'Sāvatthī.',
  'The same eight factors, then a measure of their worth. Rule over the sixteen great nations of India, with all their wealth, is not worth a sixteenth of the uposatha well kept. A day of the Four Great Kings\' heaven is fifty human years; their life is five hundred of such years.',
  ['The eight factors, each in imitation of the arahants.',
   'Human kingship is "poor beside divine happiness".',
   'The lifespans of the six sense-sphere heavens, as the measure of the fruit.'],
  ['uposatha', 'precepts'], ['an8.41', 'an8.43']),
'an8.43': S('Visākhā\'s Uposatha', 'Visākhā Sutta', 'Sāvatthī, the Eastern Monastery. Taught to the laywoman Visākhā.',
  'The uposatha with eight factors explained to Visākhā, the greatest laywoman supporter, with its fruit measured against human sovereignty and the heavens.',
  ['The eight factors.', 'Their fruit beside kingship and divine life.', 'Verses: women and men who keep it are reborn in heaven.'],
  ['uposatha', 'precepts'], ['an8.42', 'an3.70']),
'an9.18': S('The Uposatha with Nine Factors', 'Navaṅguposatha Sutta', 'Sāvatthī.',
  'The eight precepts with a ninth factor: **dwelling with a heart of loving-kindness** that spreads in every direction, above, below and across, abundant and boundless. This is the canonical basis of the nine-precept observance (*navaṅga sīla*).',
  ['The eight uposatha precepts.', 'The ninth: mettā pervading the whole world.', 'Great fruit, great glory, great radiance.'],
  ['uposatha', 'mettā', 'precepts'], ['an8.41', 'snp1.8']),
'an5.198': S('Well-Spoken Words', 'Vācā Sutta', 'Sāvatthī.',
  'Speech with five factors is well spoken, blameless and not faulted by the wise: it is spoken **at the right time**, it is **true**, it is **gentle**, it is **beneficial**, and it is spoken **with a mind of love**.',
  ['At the right time (*kāla*).', 'True (*sacca*).', 'Gentle (*saṇha*).', 'Beneficial (*atthasaṃhita*).', 'With a loving mind (*mettacitta*).'],
  ['speech'], ['mn58', 'an4.183'],
  'Before an email or a difficult conversation, run the five checks. Most regretted words fail on timing or on the last one, the state of heart they were spoken from.'),
'mn58': S('Prince Abhaya', 'Abhayarājakumāra Sutta', 'Rājagaha. The Jain leader sends Prince Abhaya with a trick question meant to corner the Buddha: would you ever say something that hurts another?',
  'Prince Abhaya has his baby son on his lap. The Buddha answers with an example from his own home: if the child put a stick or a pebble in his mouth, you would remove it even if it drew blood, out of compassion. Then he gives the most precise teaching on speech in the canon: whether to speak depends on three things — is it true, is it beneficial, is it welcome — and also on the right time.',
  ['Untrue, harmful, unwelcome: he does not say it.', 'True but harmful: he does not say it.',
   'True, beneficial but unwelcome: he knows the right time to say it.',
   'True, beneficial and welcome: he knows the right time to say it.',
   'All of it from compassion for beings.'],
  ['speech', 'compassion', 'leadership'], ['an5.198', 'an4.100']),
'an4.100': S('Potaliya', 'Potaliya Sutta', 'Sāvatthī. The wanderer Potaliya thinks the best person is the one who neither praises nor criticises.',
  'Four kinds of people: those who criticise the blameworthy truly and at the right time but do not praise; those who praise but do not criticise; those who do neither; and those who do both, truly and at the right time. The Buddha says the last is best: "knowing the right time" is the excellent thing.',
  ['Equanimity that never praises or corrects is not the highest.',
   'The best person speaks both praise and criticism, truthfully and at the right time.'],
  ['speech', 'feedback', 'leadership'], ['mn58', 'an5.198']),
'an4.183': S('What Has Been Heard', 'Suta Sutta', 'Rājagaha. The chief minister Vassakāra claims there is no fault in speaking of whatever one has seen, heard, sensed or known.',
  'The Buddha disagrees. Not everything seen, heard, sensed or known should be spoken. The test is the effect: if saying it makes unwholesome qualities grow and wholesome ones decline, it should not be said; if the reverse, it should.',
  ['Truth alone is not the test for speech.', 'Ask what the words will cause to grow, in yourself and in others.'],
  ['speech', 'discretion'], ['mn58', 'an4.187']),
'an10.176': S('Cunda the Smith', 'Cunda Sutta', 'Pāvā, Cunda\'s mango grove. Cunda describes the purification rites of the western brahmins: touching earth and cow dung, bathing three times, tending fire.',
  'The Buddha replaces ritual purity with ethical purity. There are three kinds of impurity of body, four of speech and three of mind: the ten unwholesome courses of action. Someone who does them is impure whether or not they touch the earth at dawn; someone who refrains is pure.',
  ['**Body:** killing, stealing, sexual misconduct.', '**Speech:** lying, divisive, harsh and idle speech.', '**Mind:** covetousness, ill will, wrong view.',
   'Purity is these ten given up, not a rite performed.'],
  ['ethics', 'ritual', 'karma'], ['mn41', 'sn42.6']),
'an5.161': S('Removing Resentment', 'Āghātapaṭivinaya Sutta', 'Sāvatthī.',
  'Five ways to remove resentment toward a person, whatever it has grown from: develop **loving-kindness** for them; develop **compassion**; develop **equanimity**; **stop paying attention** to them; and reflect that they are **the owner of their own deeds**.',
  ['Mettā toward that person.', 'Compassion toward that person.', 'Equanimity toward that person.', 'Disregard: do not keep turning the mind to them.',
   'Kamma: "This person owns their deeds and will inherit them."'],
  ['anger', 'relationships', 'mettā'], ['an7.64', 'mn21'],
  'A toolkit in order of gentleness. When love will not come, try compassion; when compassion will not come, equanimity; when none will come, simply stop feeding the thought; and finally hand the matter over to kamma.'),
'an7.64': S('An Angry Person', 'Kodhana Sutta', 'Sāvatthī.',
  'Seven things an enemy wishes on you, which an angry person does to themselves: to be ugly, to sleep badly, to fail to prosper, to lose wealth, to lose reputation, to lose friends, and to be reborn in a bad place. The long verses describe anger as it really is: it blinds, it wounds the family, it can even drive a person to self-harm, and it is the root of much regret.',
  ['Anger fulfils the enemy\'s seven wishes.', '"An angry person does not know what is good."',
   'Self-control, wisdom, energy and right view burn anger out like a fire out of fuel.'],
  ['anger', 'relationships'], ['an5.161', 'sn7.2']),
'sn7.2': S('Abuse', 'Akkosa Sutta', 'Rājagaha. The brahmin Akkosaka Bhāradvāja, furious that his clansman has become a monk, insults the Buddha to his face.',
  'The Buddha asks him: when guests do not accept the food you offer, whose is it? "Mine." So too: "I do not accept your abuse. It is yours, brahmin." The verses that follow are a classic on patience.',
  ['Abuse not accepted stays with the one who gave it.',
   'Repaying anger with anger is worse; not repaying it wins a battle hard to win.',
   'Staying calm when another is angry heals both: oneself and the other.'],
  ['anger', 'speech', 'patience'], ['mn21', 'an7.64']),
'mn21': S('The Simile of the Saw', 'Kakacūpama Sutta', 'Sāvatthī. Venerable Moḷiyaphagguna mixes too closely with the nuns and flares up when they are criticised.',
  'One of the great teachings on patience. People will speak to you in five ways: timely or untimely, true or false, gentle or harsh, beneficial or harmful, with love or with hate. In every case: "Our minds will be unaffected; we will dwell with a heart of love." Even if bandits sawed you limb from limb, one who gave way to hate would not be following the teaching.',
  ['The housewife Vedehikā was known as gentle until her maid tested her by sleeping in: gentleness is proven only when tested.',
   'The five ways others may speak to us.',
   'Similes: the earth that cannot be dug away, space that cannot be painted, the Ganges that cannot be heated with a grass torch, the soft catskin bag that does not rustle.',
   'The saw: even then, mettā.'],
  ['patience', 'anger', 'speech', 'mettā'], ['sn7.2', 'an5.161']),
}

LAY2_STATE = {
'sn3.1': S('Young', 'Dahara Sutta', 'Sāvatthī. King Pasenadi of Kosala meets the Buddha for the first time.',
  'The king doubts that someone so young can claim full awakening when older teachers do not. The Buddha names four things not to be looked down on because they are young: **a prince, a snake, a fire and a mendicant**. Pasenadi goes for refuge.',
  ['A young prince may become king and take revenge.', 'A small snake can kill.', 'A small fire can burn a forest.', 'A young mendicant may be fully awakened.'],
  ['leadership', 'humility'], ['sn3.2', 'mn89']),
'sn3.2': S('A Person', 'Purisa Sutta', 'Sāvatthī.',
  'What arises within a person to their harm? **Greed, hatred and delusion**. They destroy the one in whom they arise, as a reed is destroyed by its own fruit.',
  ['The three roots of the unwholesome.', 'They harm the very one who harbours them.'], ['mind', 'ethics'], ['sn3.23']),
'sn3.3': S('Old Age and Death', 'Rāja Sutta · Jarāmaraṇa Sutta', 'Sāvatthī.',
  'Is anyone born free of old age and death? No one: not the wealthy, not the learned, not even the arahants, whose bodies break up too. Royal chariots wear out, but the Dhamma of the good does not grow old.',
  ['No one born is free of ageing and death.', '"The Dhamma of the good does not decay."'], ['ageing', 'death'], ['an5.48', 'sn3.25']),
'sn3.4': S('Dear', 'Piya Sutta', 'Sāvatthī. The king reports a reflection from his own retreat.',
  'Those who do wrong in body, speech and mind treat themselves as an enemy would, even if they say "I love myself". Those who do good love themselves, even if they say they do not.',
  ['Self-love is shown by conduct, not by words.', 'Good deeds are the real kindness to oneself.'], ['ethics', 'self'], ['sn3.5', 'sn3.8']),
'sn3.5': S('Self-Protected', 'Attarakkhita Sutta', 'Sāvatthī.',
  'A wrongdoer surrounded by elephants, cavalry, chariots and infantry is still unprotected, because the protection is outside. Someone of good conduct with no army is protected, because the protection is within.',
  ['Real protection is internal: restraint of body, speech and mind.'], ['ethics', 'security'], ['sn3.4']),
'sn3.6': S('Few', 'Appaka Sutta', 'Sāvatthī.',
  'Few in the world, having gained great wealth, are not intoxicated by it, careless, greedy for pleasures and unjust to others. Many are. Like deer falling into a trap they do not see.',
  ['Wealth tests character.', 'The rich who stay sober and fair are rare.'], ['wealth', 'character'], ['an10.91', 'sn3.19']),
'sn3.7': S('In the Court', 'Atthakaraṇa Sutta', 'Sāvatthī. The king, sitting in judgement.',
  'Pasenadi tells the Buddha he has had enough of judging cases: he sees wealthy nobles, brahmins and householders lying knowingly for the sake of pleasure and gain. The Buddha agrees that this leads to long harm.',
  ['Justice is corrupted by greed at every level of society.', 'The king\'s weariness is itself a moral observation.'], ['justice', 'honesty'], ['an4.70', 'dn26']),
'sn3.8': S('Mallikā', 'Mallikā Sutta', 'Sāvatthī. In the palace, the king asks Queen Mallikā whether anyone is dearer to her than herself.',
  'Mallikā answers honestly: no one, and asks him the same. He agrees. The Buddha confirms it: search every direction and you will find no one dearer than yourself. And since others too love themselves, one who loves himself should not harm another.',
  ['No one is dearer than oneself.', 'Others feel the same about themselves.', 'Therefore do not harm others: the Golden Rule grounded in honest self-knowledge.'],
  ['ethics', 'marriage', 'golden rule'], ['sn55.7', 'sn3.4']),
'sn3.9': S('Sacrifice', 'Yañña Sutta', 'Sāvatthī. A great animal sacrifice is being prepared for the king; the servants weep as they work.',
  'The Buddha says the great Vedic sacrifices of horse and man do not bear great fruit. Sacrifices without slaughter, offered regularly to the virtuous, do.',
  ['Sacrifice that requires killing is not of great fruit.', 'Bloodless offerings to the good are.'], ['ritual', 'harmlessness'], ['dn5']),
'sn3.10': S('Bonds', 'Bandhana Sutta', 'Sāvatthī. The king has many people put in chains.',
  'The wise do not call iron, wood or rope a strong bond. Infatuation with jewels, children and partners is the strong bond. It holds us down, and it is hard to escape.',
  ['Attachment is the real prison.'], ['justice', 'attachment'], ['sn3.7']),
'sn3.11': S('Seven Matted-Hair Ascetics', 'Sattajaṭila Sutta', 'Sāvatthī, the Eastern Monastery. The king pays homage to a group of passing ascetics.',
  'It is hard for a householder to know who is an arahant. **Virtue is known by living with someone, integrity by dealing with them, resilience in adversity, wisdom in discussion**, and only over a long time, by one who is attentive and wise. Pasenadi then admits the ascetics were his own spies.',
  ['Four ways to know a person: living together, dealing together, adversity, discussion.',
   'Over a long time, with attention and wisdom.',
   'Do not judge by appearance.'],
  ['judgement', 'leadership', 'people'], ['an4.187', 'sn3.18'],
  'Perhaps the best due-diligence advice in the canon. Character shows in shared life, in business dealings, under pressure and in conversation, and it takes time to see.'),
'sn3.12': S('Five Kings', 'Pañcarāja Sutta', 'Sāvatthī. Five kings, Pasenadi among them, debate which of the senses gives the highest pleasure.',
  'The Buddha says the highest pleasure is whatever is most agreeable to each person: preference, not the object, sets the limit. The lay follower Candanaṅgalika then praises the Buddha in verse, and the five kings give him five robes.',
  ['The "best" pleasure is subjective.'], ['pleasure', 'kings'], ['sn3.6']),
'sn3.14': S('The Battle (1)', 'Paṭhamasaṅgāma Sutta', 'Kosala. Pasenadi is defeated in battle by his nephew Ajātasattu of Magadha.',
  'The Buddha\'s verse on war: **victory breeds enmity; the defeated sleep in pain. The peaceful sleep at ease, having given up victory and defeat.**',
  ['Victory begets hatred; defeat begets suffering.', 'Peace is beyond both.'], ['war', 'statecraft'], ['sn3.15', 'an7.22']),
'sn3.15': S('The Battle (2)', 'Dutiyasaṅgāma Sutta', 'Kosala. In a later battle Pasenadi wins and captures Ajātasattu alive.',
  'He confiscates the army but spares his nephew. The Buddha comments: a man plunders while it suits him, then others plunder him. **The killer gets a killer, the conqueror a conqueror**; by the turning of deeds, the plunderer is plundered.',
  ['Mercy in victory.', 'Violence returns: "by the evolution of deeds."'], ['war', 'karma'], ['sn3.14']),
'sn3.16': S('A Daughter', 'Dhītu Sutta · Mallikā Sutta', 'Sāvatthī. News arrives that Queen Mallikā has given birth to a daughter, and the king is displeased.',
  'The Buddha corrects him: **a daughter may turn out better than a son**: wise, virtuous, respectful to her husband\'s family and devoted. The son she bears may become a hero and a ruler.',
  ['A daughter is not a lesser birth.', 'Wisdom and virtue, not gender, decide worth.'], ['family', 'daughters'], ['sn3.8', 'an5.33']),
'sn3.18': S('Good Friends', 'Kalyāṇamitta Sutta', 'Sāvatthī.',
  'Pasenadi reflects that the Dhamma is for one with good friends. The Buddha recalls telling Ānanda that good friendship is **the whole of the spiritual life**. He tells the king to rely on diligence (*appamāda*): then his queens, his court, his army and the people will be diligent too, and his treasury will be protected.',
  ['"Good friendship is the whole of the holy life."', 'A diligent ruler makes a diligent people.'], ['friendship', 'leadership', 'diligence'], ['sn3.17', 'an8.54']),
'sn3.21': S('Persons', 'Puggala Sutta', 'Sāvatthī.',
  'Four kinds of people: from **dark to dark**, **dark to light**, **light to dark** and **light to light**. Birth into hardship or privilege is not destiny; conduct decides where one goes.',
  ['Born low, living badly: dark to dark.', 'Born low, living well: dark to light.', 'Born high, living badly: light to dark.', 'Born high, living well: light to light.'],
  ['karma', 'social mobility'], ['mn135', 'an5.175']),
'sn3.22': S('Grandmother', 'Ayyikā Sutta', 'Sāvatthī. The king comes in the middle of the day: his grandmother has died at the age of one hundred and twenty.',
  'He would have given an elephant, a horse, a village, even the country, to keep her alive. The Buddha: all beings die, like a potter\'s vessels, baked or unbaked. The good one has done is a support in the next world.',
  ['All beings end in death.', 'Merit is the support beyond this life.'], ['grief', 'death', 'family'], ['an5.49', 'snp3.8']),
'sn3.23': S('The World', 'Loka Sutta', 'Sāvatthī.',
  'Three things arise in the world for harm, suffering and discomfort: **greed, hatred and delusion**.', ['The three roots again, as the source of the world\'s troubles.'], ['mind'], ['sn3.2']),
'sn3.24': S('Archery', 'Issattha Sutta', 'Sāvatthī. The king asks where a gift should be given.',
  'Two different questions, the Buddha says. **Where should one give?** Wherever the heart has confidence. **Where is a gift most fruitful?** In the virtuous, free of the five hindrances. As a king hires an archer for skill, not for caste, so the worth of a recipient lies in their qualities, not their birth.',
  ['Give where the heart is inspired.', 'Great fruit comes from giving to the virtuous.', 'Merit, not birth: the archer simile.'],
  ['giving', 'merit'], ['an3.57', 'mn142']),
'dn2': S('The Fruits of the Contemplative Life', 'Sāmaññaphala Sutta', 'Rājagaha, a full-moon night in Kattika. King Ajātasattu, who had his father killed, cannot rest and asks to visit a teacher.',
  'He has asked six famous teachers what visible fruit the contemplative life brings, and found their answers empty. The Buddha begins simply: even a servant or a farmer who goes forth is honoured by the king himself. Then he lays out the whole path, fruit by fruit: virtue, sense restraint, contentment, abandoning the hindrances, the four jhānas with their similes, and the knowledges up to liberation. The king confesses his crime.',
  ['A complete map of the gradual path.', 'The hindrances as debt, illness, prison, slavery and a desert crossing.',
   'The jhāna similes: bath powder kneaded with water, a lake fed from within, lotuses immersed, a man wrapped in white cloth.',
   'The Buddha later says that had the king not killed his father, the eye of the Dhamma would have opened in him then.'],
  ['kings', 'meditation', 'karma', 'path'], ['dn5', 'an5.28']),
'dn17': S('King Mahāsudassana', 'Mahāsudassana Sutta', 'Kusinārā, as the Buddha lies on his final bed. Ānanda wishes he would not pass away in such a small town.',
  'The Buddha tells him that Kusinārā was once the royal city Kusāvatī, capital of the great king Mahāsudassana. He had seven treasures, four kinds of success and a palace of the Dhamma, yet he withdrew to practise the jhānas and the divine abodes. All of it has vanished: "How impermanent are conditions."',
  ['The ideal king: generous, righteous, beloved.', 'Even perfect worldly success is let go.', '*Aniccā vata saṅkhārā*: the verse chanted at Sri Lankan funerals.'],
  ['kings', 'impermanence', 'renunciation'], ['dn26', 'mn83']),
'mn82': S('Raṭṭhapāla', 'Raṭṭhapāla Sutta', 'Thullakoṭṭhita, Kuru country. A wealthy young man fasts until his parents allow him to go forth. Years later, as an arahant, he visits home and declines his inheritance.',
  'King Koravya asks why he went forth, since he had suffered none of the four losses (old age, illness, wealth, relatives). Raṭṭhapāla answers with **four summaries of the Dhamma**, each proven by questioning the king about his own life.',
  ['**The world is unstable; it is swept away.**', '**The world has no shelter and no protector.**',
   '**The world owns nothing; one must go on leaving everything.**', '**The world is wanting, insatiable, the slave of craving.**'],
  ['kings', 'renunciation', 'impermanence'], ['mn83', 'sn3.25']),
'mn83': S('King Maghadeva', 'Maghadeva Sutta · Makhādeva Sutta', 'Mithilā, Maghadeva\'s mango grove. The Buddha smiles at a certain spot and tells its story.',
  'A dynasty of righteous kings, each of whom, on finding his first grey hair, crowned his son and went forth. The custom held for generations, until a king broke it. That good custom led to the Brahmā realm; the Buddha\'s good custom, the eightfold path, leads to nibbāna. "Don\'t be the last man to keep it."',
  ['The grey hair as a divine messenger.', 'Righteous succession: hand on the kingdom while still well.', 'Do not be the one who breaks a good tradition.'],
  ['kings', 'succession', 'ageing'], ['an3.36', 'dn17']),
'mn89': S('Monuments to the Dhamma', 'Dhammacetiya Sutta', 'Medaḷumpa, among the Sakyans. The aged King Pasenadi visits the Buddha, kisses his feet, and declares his love.',
  'Asked why, the king gives ten reasons for his faith, which the Buddha calls **monuments to the Dhamma**: monks who live in harmony like milk and water, while kings, brahmins and families quarrel; disciples who stay devoted for life; even his own ministers who prefer the Buddha\'s teaching to the king\'s favour. Meanwhile his general has taken the royal regalia; the king will soon die in exile.',
  ['The Saṅgha\'s harmony as evidence of the Teaching.', 'Faith grounded in what one has seen.', 'The poignancy of a king at the end of power.'],
  ['kings', 'faith', 'saṅgha'], ['mn90', 'sn3.1']),
'mn90': S('At Kaṇṇakatthala', 'Kaṇṇakatthala Sutta', 'Ujuññā, the deer park at Kaṇṇakatthala. King Pasenadi questions the Buddha.',
  'The king asks about omniscience, the four castes, the gods and Brahmā. On caste, the Buddha says that among those who strive in the five factors (faith, health, honesty, energy, wisdom), there is no difference in the freedom gained, as fires of different woods give the same flame.',
  ['No one knows and sees everything at once.', 'Striving, not birth, determines liberation.'], ['kings', 'caste'], ['mn89', 'dn27']),
'mn86': S('Aṅgulimāla', 'Aṅgulimāla Sutta', 'Sāvatthī and the Kosalan forest. The Buddha walks into the territory of the killer who wears a garland of fingers.',
  '"Stop, ascetic!" — "I have stopped, Aṅgulimāla; you stop too." The killer becomes a monk. King Pasenadi arrives with an army to capture him and finds a mendicant. The sutta contains the **Aṅgulimāla paritta**, chanted for women in labour, and the verse: one who covers bad deeds with good lights up the world like the moon freed from cloud.',
  ['No one is beyond redemption.', 'The king who comes with soldiers is shown peace that force could not achieve.',
   'The paritta: "Since my noble birth, I do not recall intentionally taking life. By this truth, may you be well, and your child."'],
  ['kings', 'redemption', 'paritta', 'justice'], ['mn89', 'kp6']),
'mn108': S('Gopaka Moggallāna', 'Gopakamoggallāna Sutta', 'Rājagaha, soon after the Buddha\'s death. The city is being fortified against King Pajjota; the chief minister Vassakāra questions Ānanda.',
  'Is there a single monk the Buddha appointed as successor, or whom the Saṅgha has chosen? No. Then how does the Saṅgha stay united? "We are not without refuge; **the Dhamma is our refuge**." Ānanda describes the ten qualities that make a monk worthy of respect, and the institution that works by principle rather than by a leader.',
  ['No successor: the Dhamma and the training rules govern.', 'Ten qualities that inspire confidence.', 'Institutional continuity without a single head.'],
  ['institutions', 'succession', 'leadership'], ['dn16x', 'an7.21']),
'an7.21': S('At Sārandada', 'Sārandada Sutta', 'Vesālī, the Sārandada shrine. The Licchavis come to the Buddha.',
  'Seven principles of non-decline for a republic: **meet often and in full; meet, act and disperse in harmony; do not legislate arbitrarily, keep the established law; honour the elders; do not abduct women and girls; maintain the shrines and their offerings; protect the arahants.** As long as they keep these, only growth is to be expected.',
  ['Frequent, full assemblies.', 'Concord in meeting and acting.', 'Rule of law, not of whim.', 'Respect for elders.', 'Protection of women.', 'Care of sacred places.', 'Protection of the holy.'],
  ['statecraft', 'governance', 'institutions'], ['an7.22', 'dn16x']),
'an7.22': S('Vassakāra', 'Vassakāra Sutta', 'Rājagaha, Vulture\'s Peak. King Ajātasattu wants to destroy the Vajjians and sends his chief minister to sound out the Buddha.',
  'The Buddha asks Ānanda whether the Vajjians still keep the seven principles. They do. Vassakāra draws the conclusion: they cannot be defeated in war, except by bribery or by breaking their unity. Then the Buddha applies the same principles to the Saṅgha.',
  ['A united, lawful people is not conquered by force.', 'Their weak points are corruption and division.'],
  ['statecraft', 'war', 'unity'], ['an7.21', 'sn3.14']),
'an4.187': S('Vassakāra on Judging People', 'Vassakāra Sutta · Dutiyavassakāra Sutta', 'Rājagaha. Vassakāra asks whether a bad person can recognise a good one.',
  'A bad person cannot know a bad person, nor a good one. A good person can know both. It takes goodness to judge character.',
  ['Only the good can judge goodness, and badness, accurately.'], ['judgement', 'people'], ['sn3.11', 'an4.183']),
'an5.49': S('Kosala', 'Kosala Sutta', 'Sāvatthī. As King Pasenadi sits with the Buddha, a man whispers in his ear that Queen Mallikā has died.',
  'The king sits slumped, shoulders drooping, lost for words. The Buddha teaches the **five things no one can obtain**: that what is subject to ageing should not age, sickness not sicken, death not die, ending not end, perishing not perish.',
  ['Five things unobtainable by anyone in the world.', 'The wise, reflecting, do not sorrow; the arrow is pulled out.'],
  ['grief', 'death', 'marriage'], ['an5.48', 'an5.50', 'sn3.8']),
'an5.50': S('Nārada', 'Nārada Sutta · Sokasallaharaṇa Sutta', 'Pāṭaliputta. King Muṇḍa\'s beloved Queen Bhaddā has died; he will not bathe or eat, neglects the kingdom, and broods over her body.',
  'His treasurer takes him to Venerable Nārada, who teaches the five unobtainable things and the verses on grief. The king puts down his sorrow, has the body cremated, builds a memorial, and returns to his duties. BJT names it "the removing of the dart of sorrow".',
  ['Grief does not bring back the dead, and it delights one\'s enemies.', 'The arrow of sorrow can be drawn out.'],
  ['grief', 'kings', 'duty'], ['an5.49', 'snp3.8']),
'sn55.1': S('A Wheel-Turning King', 'Cakkavattirāja Sutta · Rāja Sutta', 'Sāvatthī.',
  'A wheel-turning monarch rules the four continents and is reborn in heaven, yet without four qualities he is not free from the lower realms. A noble disciple who lives on scraps and wears rags, but has **confidence in the Buddha, the Dhamma and the Saṅgha, and the virtue dear to the noble ones**, is free of them. The four continents are not worth a sixteenth of these four.',
  ['The four factors of stream-entry.', 'World empire is worth less than inner assurance.'],
  ['kings', 'stream-entry', 'faith'], ['an5.179', 'sn55.7']),
}
LAY2.update(LAY2_STATE)

LAY2_FAITH = {
'an8.25': S('Who Is a Lay Follower?', 'Mahānāma Sutta', 'Kapilavatthu, the Banyan Monastery. The Buddha\'s cousin Mahānāma asks.',
  'One who has gone for refuge to the Buddha, the Dhamma and the Saṅgha is a lay follower. A **virtuous** lay follower keeps the five precepts. A lay follower practising **for their own good** has faith, virtue and generosity, likes to see monastics, listens, remembers, examines the meaning and practises accordingly. One practising **for the good of both** also encourages others in each of these.',
  ['Refuge makes a lay follower.', 'The five precepts make a virtuous one.', 'Eight qualities for one\'s own good.', 'Encouraging others in them: for the good of both.'],
  ['refuge', 'lay life', 'faith'], ['sn55.37', 'an5.179']),
'an5.175': S('The Outcaste Lay Follower', 'Caṇḍāla Sutta · Upāsakacaṇḍāla Sutta', 'Sāvatthī.',
  'A lay follower with five qualities is an "outcaste", a stain: **faithless, unvirtuous, superstitious** (relying on omens and lucky signs rather than deeds), **seeking recipients outside the Dispensation**, and **serving them first**. One with the opposite five is a jewel, a lotus.',
  ['Outcaste by conduct, not birth.', 'Superstition (*kotūhalamaṅgala*): trusting omens over kamma.', 'The jewel lay follower trusts deeds, not signs.'],
  ['faith', 'superstition', 'lay life'], ['an5.179', 'kp5'],
  'A gentle but firm word against horoscope-driven life. The Buddha does not mock the search for good fortune; he points to its real source, which is conduct.'),
'an5.179': S('The Householder', 'Gihi Sutta', 'Sāvatthī. Anāthapiṇḍika comes with five hundred lay followers; the Buddha addresses Sāriputta.',
  'A lay person who is restrained in the five precepts and gains, whenever they wish, **four pleasant abidings in this very life** (confidence in the Buddha, the Dhamma, the Saṅgha, and the virtue dear to the noble ones) may declare: I am a stream-enterer, no longer bound for the lower realms.',
  ['Stream-entry is open to householders.', 'Five precepts plus four kinds of confidence.', 'The four "heavenly abidings of the higher mind" (*ābhicetasika diṭṭhadhammasukhavihāra*).'],
  ['stream-entry', 'lay life', 'precepts'], ['sn55.7', 'an10.92']),
'sn55.7': S('The People of Bamboo Gate', 'Veḷudvāreyya Sutta', 'The Kosalan village of Veḷudvāra. The brahmin householders ask: we want family, fine clothes, perfumes and money, and a good rebirth. Teach us accordingly.',
  'The Buddha teaches the **Golden Rule** in its fullest canonical form. "I want to live and don\'t want to die; I want happiness and dislike pain. If someone took my life, I would not like it. Others feel the same. How could I do to another what I would not want done to me?" Applied to killing, stealing, adultery, lying, divisive, harsh and idle speech. With the four factors of stream-entry, it leads to the stream.',
  ['Reflect on yourself, then extend it to others: *attūpanāyika dhammapariyāya*.', 'Refrain, encourage others to refrain, and praise refraining.', 'The four factors of stream-entry.'],
  ['golden rule', 'ethics', 'stream-entry'], ['sn3.8', 'an5.179'],
  'This is the sutta to give anyone who asks what Buddhist ethics is, in one page.'),
'sn55.37': S('Mahānāma on Lay Accomplishment', 'Mahānāma Sutta', 'Kapilavatthu.',
  'What makes a lay follower accomplished in **virtue, faith, generosity and wisdom**? The precepts; faith in the Buddha\'s awakening; living at home with a heart free of stinginess, open-handed, devoted to charity, loving to give and share; and the wisdom that sees rise and fall.',
  ['The four lay accomplishments.', 'A classic description of a generous heart: *muttacāgo payatapāṇi vossaggarato yācayogo dānasaṃvibhāgarato*.'],
  ['lay life', 'generosity', 'faith'], ['an8.25', 'an8.54']),
'an3.65': S('The Kālāmas', 'Kesamutti Sutta · Kālāma Sutta', 'Kesamutta, the town of the Kālāmas, who are confused by teachers each praising their own doctrine.',
  'Do not go by oral tradition, lineage, testimony, scripture, logic, inference, reasoned thought, a favoured view, the speaker\'s apparent competence, or "this ascetic is our teacher". **When you know for yourselves** that things are unskilful, blameworthy, criticised by the wise and lead to harm, give them up. The Buddha then leads them to see this of greed, hatred and delusion, and teaches the divine abodes and the **four assurances**.',
  ['Ten unreliable grounds for belief.', 'The test: harm or benefit, praised or blamed by the wise, known for oneself.',
   'The four assurances: if there is a next world, I go to a good place; if not, I live happily here; if evil befalls evildoers, I do none; if not, I am purified either way.'],
  ['faith', 'inquiry', 'mettā'], ['sn42.13', 'an10.92']),
'an8.21': S('Ugga of Vesālī', 'Ugga Sutta', 'Vesālī. The Buddha praises the householder Ugga for eight wonderful qualities; a monk goes to ask Ugga what they are.',
  'Ugga tells his own story: faith at first sight of the Buddha; awakening to the Dhamma; taking the precepts of celibacy and, with care and fairness, releasing his four young wives, giving one in marriage to the man she chose; sharing his wealth with the virtuous; serving monastics with respect; listening; not being elated when deities spoke to him; and being free of the five lower fetters.',
  ['A householder non-returner.', 'Wealth shared with the good.', 'Humility even in spiritual attainment.'],
  ['lay life', 'awakening', 'generosity'], ['an8.23', 'an6.119']),
'an8.23': S('Hatthaka of Āḷavī', 'Hatthaka Sutta', 'Āḷavī. The Buddha praises the householder Hatthaka for seven qualities.',
  'Hatthaka has faith, virtue, conscience, prudence, learning, generosity and wisdom. When he hears the Buddha has praised him, he asks that no householder in white was present: he doesn\'t want praise. The Buddha adds an eighth quality: **modesty**.',
  ['The seven noble treasures, embodied.', 'The eighth: not wanting one\'s virtues known.'],
  ['lay life', 'humility'], ['an8.21', 'an7.6']),
'an9.20': S('Velāma', 'Velāma Sutta', 'Sāvatthī. Anāthapiṇḍika says the alms his family gives are coarse.',
  'The Buddha tells of the brahmin Velāma, his own past life, who gave an immense gift: gold, silver, elephants, chariots, cows. But more fruitful than that is feeding one person of right view; more again a stream-enterer, and so on up to a Buddha and the Saṅgha; a monastery; going for refuge; the precepts; **a moment of loving-kindness as long as it takes to pull a cow\'s udder**; and most fruitful of all, **perceiving impermanence for the time of a finger-snap**.',
  ['The scale of merit, from material gifts to insight.', 'Quality of recipient and quality of mind outweigh quantity.', 'Insight into impermanence crowns all giving.'],
  ['giving', 'merit', 'impermanence'], ['mn142', 'an8.36']),
'an10.92': S('Dangers', 'Bhaya Sutta · Vera Sutta', 'Sāvatthī. Taught to Anāthapiṇḍika.',
  'A noble disciple who has calmed **five dangers and enmities** (killing, stealing, sexual misconduct, lying and intoxication), has the **four factors of stream-entry**, and has **seen and understood the noble method** (dependent origination) may declare themselves a stream-enterer.',
  ['Five fears and enmities: what the precepts protect against, here and hereafter.', 'The four factors.', 'Dependent origination as "the noble method" (*ariyo ñāyo*).'],
  ['stream-entry', 'precepts'], ['an5.179', 'sn55.7']),
'mn143': S('Advice to Anāthapiṇḍika', 'Anāthapiṇḍikovāda Sutta', 'Sāvatthī. Anāthapiṇḍika is gravely ill. Sāriputta and Ānanda visit.',
  'Sāriputta teaches him to cling to nothing: not the eye or what it sees, not consciousness, not the elements, not the aggregates, not this world or the next, nothing seen, heard, thought or known. Anāthapiṇḍika weeps: in all his years he has never heard such a teaching, and asks that householders be taught it too. He dies and is reborn in Tusita, and returns that night to praise Jetavana.',
  ['Non-clinging to every sense and every world.', '"Let such talks be given to householders too: some have little dust in their eyes."', 'The great patron\'s death.'],
  ['death', 'illness', 'non-attachment'], ['sn55.26', 'sn55.54']),
'sn55.26': S('Anāthapiṇḍika Is Ill', 'Anāthapiṇḍika Sutta', 'Sāvatthī. Sāriputta visits the sick householder.',
  'Sāriputta reminds him: you do not have the lack of faith, the bad conduct and wrong path factors that lead an ordinary person to the lower realms. You have confidence in the Buddha, Dhamma and Saṅgha, noble virtue, and right view through right freedom. As Anāthapiṇḍika reflects on this, his pain subsides.',
  ['Recollecting one\'s own good as medicine.', 'The bedside role of a spiritual friend.'],
  ['illness', 'faith', 'recollection'], ['mn143', 'sn55.54']),
'sn55.40': S('Nandiya the Sakyan', 'Nandiya Sutta', 'Kapilavatthu.',
  'A stream-enterer can still be **negligent**: content with confidence and virtue, they make no further effort for seclusion and concentration, and their progress stalls. The diligent one goes further: joy, rapture, tranquillity, happiness, concentration, and the truths become clear.',
  ['Stream-entry is not a finish line.', 'Diligence (*appamāda*) carries one on.'],
  ['diligence', 'stream-entry'], ['an6.10', 'sn3.18']),
'sn55.54': S('Counselling the Sick', 'Gilāna Sutta', 'Kapilavatthu. Mahānāma asks how a wise lay follower should counsel another wise lay follower who is gravely ill.',
  'A bedside method, step by step. First reassure them with the four kinds of confidence. Ask if they worry for their parents: they will die whether you worry or not. Their partner and children: the same. Then lead the mind upward: from human pleasures to divine ones, from the heavens to the Brahmā world, and from there to the ending of identity. Such a lay follower, the Buddha says, is no different from a monk freed by wisdom.',
  ['Reassure with the four factors.', 'Release worry for family.', 'Raise the mind, realm by realm, to letting go.', 'Lay liberation is equal to monastic liberation.'],
  ['illness', 'death', 'pastoral care'], ['mn143', 'an6.16', 'an10.60'],
  'If you sit with the dying, this is your text. It is gentle, honest and practical, and it ends at the highest point.'),
'an6.16': S('Nakula\'s Parents', 'Nakulapitu Sutta', 'Among the Bhaggas. Nakulapitā is gravely ill; his wife Nakulamātā sits by him.',
  'She gives six reassurances so that he can die without worry: I can support the children by spinning; I will not take another husband; I will keep seeing the Buddha and the Saṅgha; I will keep the precepts; I will attain inner serenity; I am established in the Dhamma. He recovers, and the Buddha tells him he is fortunate to have such a wife.',
  ['A marriage as mutual spiritual support.', 'Six reassurances for a dying partner.', 'Worry is bad for the dying: the Buddha says it is painful to die anxious.'],
  ['marriage', 'illness', 'death'], ['an4.55', 'sn22.1']),
'an6.119': S('Tapussa', 'Tapussa Sutta', 'Taught to the mendicants.',
  'The householder Tapussa, who with Bhallika was the first to take refuge in the Buddha after the awakening, has seen the deathless through six qualities: unwavering confidence in the Buddha, the Dhamma and the Saṅgha, noble virtue, noble knowledge and noble freedom. The suttas that follow name many other lay people who reached the same.',
  ['Lay people realise the deathless.', 'Six qualities of a lay disciple who has seen the Dhamma.'],
  ['awakening', 'lay life'], ['an8.21', 'an5.179']),
'mn54': S('Potaliya', 'Potaliya Sutta', 'Āpaṇa, in Aṅguttarāpa. Potaliya, dressed as a renouncer, is offended at being called "householder": he has "cut off all affairs".',
  'The Buddha shows what cutting off affairs means in the noble discipline: eight kinds of abstention, from killing to arrogance. Then seven similes for sensual pleasures: a meatless bone thrown to a dog, a scrap of meat fought over by birds, a grass torch carried against the wind, a pit of coals, a dream, borrowed goods, a fruit tree others climb and cut. Then the jhānas and the three knowledges.',
  ['Renunciation is inner, not a costume.', 'Seven similes for sense pleasures, among the most vivid in the canon.'],
  ['renunciation', 'sense pleasures'], ['mn82', 'an10.91']),
'mn56': S('Upāli', 'Upāli Sutta', 'Nāḷandā. The wealthy Jain householder Upāli goes to refute the Buddha on whether physical or mental deeds are weightier.',
  'He is won over, and asks to become a follower. The Buddha tells him to think carefully, as a well-known man, and to keep giving to the Jains who depend on his family. Upāli is all the more inspired. When his former teacher comes, he praises the Buddha in a hundred epithets.',
  ['Mental intention is the weightiest kind of action.', 'Converts should keep supporting their former teachers: generosity is not sectarian.'],
  ['karma', 'intention', 'tolerance'], ['an3.57', 'mn41']),
}
LAY2.update(LAY2_FAITH)

LAY2_WORK = {
'sn42.2': S('The Actor', 'Tālapuṭa Sutta', 'Rājagaha. Tālapuṭa, the head of a theatre troupe, has heard that actors who make people laugh are reborn among the gods of laughter.',
  'The Buddha declines to answer twice. Pressed, he says: performers who inflame audiences already bound by greed, hatred and delusion, when they themselves are heedless, go to a hell, if they hold that wrong view. Tālapuṭa weeps, not at the answer but at having been deceived, and goes forth.',
  ['Art that inflames the defilements carries a cost.', 'The Buddha answers only when asked three times.'],
  ['work', 'art', 'livelihood'], ['sn42.3', 'an5.177']),
'sn42.3': S('The Soldier', 'Yodhājīva Sutta', 'Rājagaha. A professional warrior has heard that a soldier killed in battle is reborn in heaven.',
  'Pressed, the Buddha says: in battle the warrior\'s mind is already low and misdirected ("let these beings be killed, slaughtered, annihilated"); dying in that state, if he holds the heavenly view, he goes to a hell. The soldier weeps at having been deceived.',
  ['Intention at death matters.', 'No glory in killing.'],
  ['work', 'war', 'livelihood'], ['sn42.2', 'sn3.14']),
'sn42.6': S('The Western Brahmins', 'Asibandhakaputta Sutta', 'Nāḷandā. A headman asks whether the Buddha, like the western brahmins, can raise the dead to heaven by ritual.',
  'Throw a heavy rock into a lake, and pray around it for it to float: it will not. So a wrongdoer will not rise because people pray. Pour ghee or oil into the lake and pray for it to sink: it will not. So the good rise by their own deeds.',
  ['Rites and prayers do not override kamma.', 'One\'s own conduct is what rises or sinks.'],
  ['ritual', 'karma', 'death'], ['an10.176', 'kp7']),
'sn42.7': S('The Fields', 'Khettūpama Sutta', 'Nāḷandā. The headman asks why, if the Buddha has compassion for all, he teaches some more fully than others.',
  'A farmer has three fields: good, middling and poor. He sows the good one first, then the middling, and the poor one too, because it may at least yield cattle feed. So the Buddha teaches monastics, then lay followers, and even others who do not follow him: if they understand even a single line, it is for their long good.',
  ['Teaching for all, in order of readiness.', 'Even a single line can help.'],
  ['teaching', 'compassion'], ['sn42.8']),
'sn42.8': S('The Conch Blower', 'Saṅkhadhama Sutta', 'Nāḷandā. A Jain headman reports his teacher\'s view: whatever you do often decides your destiny.',
  'The Buddha shows the view is self-defeating, and that dwelling on past misdeeds only produces regret. The noble disciple instead gives up wrong deeds and spreads loving-kindness, compassion, gladness and equanimity in all directions, as a strong conch blower is heard in every quarter. Limited deeds do not remain beside such a boundless heart.',
  ['Remorse alone does not undo the past.', 'Boundless brahmavihāra outweighs limited deeds.'],
  ['karma', 'mettā', 'remorse'], ['an4.125', 'dn13']),
'sn42.9': S('Families', 'Kula Sutta', 'Nāḷandā, during a famine. The Jain leader sends a headman with a trap: does the Buddha not ruin families by going for alms in hard times?',
  'The Buddha says that in ninety-one aeons he knows of no family ruined by giving cooked alms. Rich families became rich through giving, truth and restraint. He names **eight causes of a family\'s ruin**: kings, thieves, fire, flood, lost buried treasure, failed businesses, a wastrel heir, and impermanence itself.',
  ['Giving does not ruin families.', 'Eight real causes of ruin, still recognisable today.'],
  ['wealth', 'family', 'giving'], ['an5.227', 'an4.61']),
'sn42.10': S('Maṇicūḷaka', 'Maṇicūḷaka Sutta', 'Rājagaha. In the royal court, some say Buddhist monks may accept gold and money. The headman Maṇicūḷaka disagrees, and asks the Buddha.',
  'The Buddha confirms: gold and money are not allowable for monastics. Anyone for whom they are allowable is allowed the five cords of sensual pleasure. What a monk needs, such as grass, wood or a cart, may be sought; money itself, never.',
  ['Monastics do not accept money.', 'Lay supporters provide requisites, not cash.'],
  ['monastic discipline', 'giving'], ['an4.61']),
'sn42.11': S('Bhadraka', 'Bhadraka Sutta', 'Uruvelakappa, among the Mallas. The headman asks about the origin and ending of suffering.',
  'Instead of a theory, the Buddha asks about his own life. Would he grieve if people in the town were killed or fined? Some, yes; others, no. Why the difference? Desire. And his son Ciravāsī, away from home: would he grieve if he died? "My life would be upset." And his wife: before he had seen or heard of her, did he have any love or desire for her? None. Suffering is rooted in desire.',
  ['Suffering arises from desire, as seen in our own loves.', 'The past, present and future are the same.'],
  ['suffering', 'family', 'attachment'], ['ud8.8', 'mn87']),
'sn42.12': S('Rāsiya', 'Rāsiya Sutta', 'The headman Rāsiya asks whether the Buddha condemns all asceticism.',
  'The Buddha teaches the middle way between indulgence and self-mortification, then the ten kinds of people who enjoy sensual pleasures (as in AN 10.91), and three kinds of ascetics. Wealth honestly gained, enjoyed, shared and held without bondage is praised.',
  ['The middle way.', 'Ten kinds of wealth-users.', 'Wise and foolish austerity.'],
  ['wealth', 'middle way'], ['an10.91']),
'sn42.13': S('Pāṭaliya', 'Pāṭaliya Sutta', 'Uttara, among the Koliyans. The headman asks whether the Buddha knows magic.',
  'He does, but that does not make him a magician, as knowing a killer does not make one a killer. Pāṭaliya then reports many conflicting views he has heard. The Buddha teaches a practice beyond the dispute: give up wrongdoing and fill the world with the four divine abodes. Whichever view is true, such a person has thrown the winning dice.',
  ['Knowing evil is not doing it.', 'The "incontrovertible" practice: whatever the truth, the brahmavihāras win.'],
  ['views', 'mettā', 'inquiry'], ['an3.65', 'sn42.8']),
}
LAY2.update(LAY2_WORK)

LAY2_ELDERS = {
'an3.36': S('The Divine Messengers', 'Devadūta Sutta', 'Taught to the mendicants.',
  'After death, King Yama questions a wrongdoer: did you not see the divine messengers? **A newborn child, an old person, a sick person, a criminal being punished, a corpse.** "Did you not think: I too am subject to birth, ageing, sickness and death; let me do good?" The deeds were yours, and you will experience the result.',
  ['Five messengers in ordinary life.', 'No one else made the deeds: not parents, friends, gods or ascetics.', 'The verses: the wise, seeing them, take up the Dhamma.'],
  ['ageing', 'death', 'karma', 'urgency'], ['an5.57', 'mn83']),
'an5.57': S('Five Daily Reflections', 'Abhiṇhapaccavekkhitabbaṭhāna Sutta · Upajjhatthāna Sutta', 'Taught to the mendicants, and to "a woman or a man, a householder or a renunciant".',
  'Five things to reflect on often: **I am subject to ageing; to sickness; to death; I will be separated from all that is dear; I am the owner and heir of my deeds.** Each one has a purpose: to cut the intoxication of youth, of health, of life, desire for the dear, and misconduct.',
  ['The five reflections, chanted daily in Theravāda monasteries.', 'Each answers a particular intoxication.', 'Extended to all beings, they lead to the path.'],
  ['reflection', 'ageing', 'death', 'karma'], ['an5.48', 'an3.36'],
  'Read these five lines every morning. They are not morbid; the Buddha says they make a person less reckless, less possessive and more careful with their actions.'),
'an5.48': S('Things No One Can Have', 'Alabbhanīyaṭhāna Sutta', 'Taught to the mendicants.',
  'Five things cannot be had by anyone, ascetic, brahmin, god, Māra or Brahmā: that what is subject to ageing should not age, sickness not sicken, death not die, ending not end, perishing not perish. The ordinary person, struck by these, grieves and is pierced by the arrow. The noble disciple reflects, "it is not only mine," and draws the arrow out.',
  ['Five unobtainable things.', 'Grief does not help: enemies rejoice, friends are pained.', 'Reflection removes the dart.'],
  ['grief', 'loss', 'death'], ['an5.49', 'an5.50']),
'an3.39': S('Delicate', 'Sukhumāla Sutta', 'The Buddha recalls his youth.',
  'He was raised in luxury: lotus ponds, three palaces, Kāsi sandalwood, servants fed on rice and meat. Yet reflecting that he too would age, sicken and die, and that it was not fitting to be disgusted at others\' ageing, he lost the **three intoxications: of youth, health and life**.',
  ['Privilege does not exempt anyone.', 'The three intoxications (*mada*).'],
  ['ageing', 'privilege', 'urgency'], ['an5.57', 'an3.36']),
'sn22.1': S('Nakula\'s Father', 'Nakulapitu Sutta', 'Among the Bhaggas. The aged Nakulapitā, often ill, asks for a teaching to support him.',
  'The Buddha: "Though my body is sick, my mind will not be sick." Sāriputta explains how: the ordinary person regards form, feeling, perception, formations and consciousness as self, so when they change, the mind suffers. The noble disciple does not.',
  ['A sick body, a healthy mind.', 'Non-identification with the aggregates.'],
  ['illness', 'ageing', 'not-self'], ['an6.16', 'sn55.54']),
'snp3.8': S('The Arrow', 'Salla Sutta', 'The Sutta Nipāta. The commentary says it was taught to a layman grieving for a son.',
  'Life here is short and painful, and no means exists for the born not to die. As ripe fruit must fall, as clay pots break, so with mortals. Not by weeping is peace found; grief only harms the griever. Draw out the arrow of sorrow and you will find peace.',
  ['Death is certain for all.', 'Lamenting does not help the dead or the living.', '"Pull out the arrow" (*abbahe sallam attano*).'],
  ['grief', 'death'], ['an5.48', 'ud8.8']),
'ud8.8': S('Visākhā\'s Grandchild', 'Visākhā Sutta', 'Sāvatthī. Visākhā comes in the middle of the day, clothes and hair wet: her beloved grandchild has died.',
  'Would she like to have as many children and grandchildren as there are people in Sāvatthī? Yes. And how many die in Sāvatthī each day? Many. Then she would never be without wet hair. Those with a hundred dear ones have a hundred sorrows; those with none have none.',
  ['Love and grief go together.', 'Freedom from sorrow is freedom from clinging, not from love\'s warmth.'],
  ['grief', 'family', 'attachment'], ['snp3.8', 'sn42.11']),
'mn97': S('Dhānañjāni', 'Dhānañjāni Sutta', 'Rājagaha. The brahmin Dhānañjāni has been robbing the king to support his family.',
  'Sāriputta asks: in hell, could you say "I did it for my parents, my wife, my children"? No. Family can be supported by righteous work. Later, as Dhānañjāni lies dying, Sāriputta teaches him the path to the Brahmā world through the four divine abodes. The Buddha says he could have taught him more.',
  ['Family duty never excuses wrongdoing.', 'Honest livelihood is enough to support a family.', 'At the deathbed, aim high.'],
  ['ethics', 'family', 'livelihood', 'death'], ['an4.62', 'sn55.54']),
'sn47.29': S('Sirivaḍḍha', 'Sirivaḍḍha Sutta', 'Rājagaha. The householder Sirivaḍḍha is ill and asks Ānanda to visit.',
  'Ānanda teaches him to practise the four establishments of mindfulness. He answers that he already does, and that he has given up the five lower fetters. Ānanda declares him a non-returner.',
  ['Lay meditators reach high attainment.', 'Mindfulness as the practice of the sick.'],
  ['illness', 'mindfulness', 'lay life'], ['mn10', 'sn55.54']),
}
LAY2.update(LAY2_ELDERS)
